<script setup lang="ts">
import { Save, Plus, RefreshCw } from '@lucide/vue';
const config=useRuntimeConfig(),{token}=useWorkspaceSession();
const rows=ref<any[]>([]),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),editing=ref<any>(null);
const blank=()=>({entityType:'IP',legalName:'',inn:'',kpp:'',ogrn:'',ogrnip:'',address:'',signerName:'',signerTitle:'',signerBasis:'',email:'',isActive:true});
function api(path='',options:any={}){return $fetch<any>(`/partners/admin/legal-entities${path}`,{baseURL:config.public.apiBase,headers:{Authorization:`Bearer ${token.value}`},timeout:15000,...options});}
async function load(){loading.value=true;error.value='';try{rows.value=await api();}catch(e:any){error.value=e?.data?.message||'Не удалось загрузить реквизиты';}finally{loading.value=false;}}
function edit(row?:any){editing.value=row?{...row}:{...blank()};error.value='';notice.value='';}
async function save(){if(busy.value||!editing.value)return;busy.value=true;error.value='';notice.value='';try{const {id,...body}=editing.value;await api(id?`/${id}`:'',{method:id?'PATCH':'POST',body});editing.value=null;notice.value='Профиль реквизитов сохранён';await load();}catch(e:any){error.value=Array.isArray(e?.data?.message)?e.data.message.join(' · '):e?.data?.message||'Не удалось сохранить профиль';}finally{busy.value=false;}}
onMounted(load);
</script>
<template><section class="partner-workspace crm-standard"><header class="partner-page-head crm-page-header"><div><h1>Реквизиты стороны договора</h1><p>Добавьте ваши ИП и ООО. Партнёр выберет, от чьего имени сформировать документы.</p></div><div class="partner-actions"><button class="partner-button crm-button" :disabled="loading" @click="load"><RefreshCw :size="18"/>Обновить</button><button class="partner-button partner-primary crm-button crm-button--primary" @click="edit()"><Plus :size="18"/>Добавить сторону</button></div></header><p v-if="error" class="partner-feedback" role="alert">{{error}}</p><p v-if="notice" class="partner-feedback" role="status">{{notice}}</p><div class="partner-kpis"><article v-for="row in rows" :key="row.id" class="partner-panel crm-surface"><small>{{row.entityType==='IP'?'Индивидуальный предприниматель':'Общество с ограниченной ответственностью'}} · {{row.isActive?'Активно':'Отключено'}}</small><h2>{{row.legalName}}</h2><p>ИНН {{row.inn}}<span v-if="row.kpp"> · КПП {{row.kpp}}</span></p><p>{{row.entityType==='IP'?'ОГРНИП '+row.ogrnip:'ОГРН '+row.ogrn}}</p><p>{{row.address}}</p><p>Подписант: {{row.signerName}}, {{row.signerBasis}}</p><button class="partner-button crm-button" @click="edit(row)">Изменить</button></article><p v-if="!rows.length&&!loading" class="partner-panel crm-surface">Профили пока не добавлены. Заполните реквизиты ИП и ООО, если оба варианта используются.</p></div><div v-if="editing" class="partner-panel crm-surface partner-legal-editor"><header class="partner-card-heading"><div><h2>{{editing.id?'Изменить реквизиты':'Новый профиль реквизитов'}}</h2><p>Изменения применятся к новым файлам. Уже сформированные документы сохранят исходные реквизиты.</p></div></header><form class="partner-form-grid" @submit.prevent="save"><label>Тип стороны<select class="crm-input" v-model="editing.entityType"><option value="IP">ИП</option><option value="LLC">ООО</option></select></label><label>Полное юридическое наименование<input class="crm-input" v-model="editing.legalName" required maxlength="300"/></label><label>ИНН<input class="crm-input" v-model="editing.inn" required inputmode="numeric" maxlength="12"/></label><label v-if="editing.entityType==='LLC'">КПП<input class="crm-input" v-model="editing.kpp" required inputmode="numeric" maxlength="9"/></label><label v-if="editing.entityType==='LLC'">ОГРН<input class="crm-input" v-model="editing.ogrn" required inputmode="numeric" maxlength="13"/></label><label v-if="editing.entityType==='IP'">ОГРНИП<input class="crm-input" v-model="editing.ogrnip" required inputmode="numeric" maxlength="15"/></label><label class="partner-legal-wide">Юридический/регистрационный адрес<input class="crm-input" v-model="editing.address" required maxlength="500"/></label><label>ФИО подписанта<input class="crm-input" v-model="editing.signerName" required maxlength="200"/></label><label>Должность (для ООО)<input class="crm-input" v-model="editing.signerTitle" maxlength="120" placeholder="Генеральный директор"/></label><label>Основание полномочий<input class="crm-input" v-model="editing.signerBasis" required maxlength="200" placeholder="Устав / свидетельство о регистрации ИП"/></label><label>Email<input class="crm-input" v-model="editing.email" type="email" maxlength="254"/></label><label class="partner-option"><input v-model="editing.isActive" type="checkbox"/> Доступно для выбора партнёрам</label><footer class="partner-actions partner-legal-wide"><button class="partner-button partner-primary crm-button crm-button--primary" :disabled="busy" type="submit"><Save :size="18"/>Сохранить</button><button class="partner-button crm-button" type="button" :disabled="busy" @click="editing=null">Закрыть</button></footer></form></div></section></template>
